import './neon-js-object.scss';
import { NeonWidget } from '../shared/neon-widget';
import { createElement, } from '../shared/dom-manipulation';
export class NeonJsObject extends NeonWidget {
    constructor() {
        super(...arguments);
        this.widgetTag = 'neon-js-object';
    }
    set value(value) {
        this._value = value;
        this.redraw();
    }
    get value() {
        return this._value;
    }
    //Any attribute that should be watched for changes should be listed here.
    static get observedAttributes() {
        return [];
    }
    //when the attributes change this will run
    attributeChanged(attrName, oldVal, newVal) {
        super.attributeChanged(attrName, oldVal, newVal);
        // attributeChanged is called when attributes listed in "static get observedAttributes()" are changed.
        switch (attrName) {
            // case 'data-indent-spaces':
            //   this.redraw();
            //   break;
            default:
        }
    }
    render() {
        if (this.value != null) {
            const jsonString = JSON.stringify(this.value, null, 1);
            const tokens = jsonString.split('\n');
            const tokensWithStructure = [];
            const arrayStack = [tokensWithStructure];
            let topOfStack = tokensWithStructure;
            let numIndents = 0;
            let newIndents = 0;
            for (const token of tokens) {
                const spaces = /^ */.exec(token);
                if (spaces != null && spaces.length > 0) {
                    newIndents = spaces[0].length;
                    if (newIndents > numIndents) {
                        const subArray = [];
                        topOfStack.push(subArray);
                        arrayStack.push(subArray);
                    }
                    else if (newIndents < numIndents) {
                        arrayStack.pop();
                    }
                }
                topOfStack = arrayStack[arrayStack.length - 1];
                topOfStack.push(token.trim());
                numIndents = newIndents;
            }
            return this.renderLineBlock(tokensWithStructure);
        }
    }
    renderLineBlock(tokensWithStructure) {
        return tokensWithStructure.flatMap((token) => {
            if (typeof token === 'string') {
                const colonIndex = token.indexOf(':');
                if (colonIndex >= 0) {
                    return createElement('div', {}, createElement('span', {
                        attrs: { class: 'neon-js-object-key' },
                        text: token.slice(0, colonIndex)
                    }), createElement('span', {
                        text: token.slice(colonIndex)
                    }));
                }
                else {
                    return createElement('span', {
                        text: token
                    });
                }
            }
            else {
                return createElement('div', { attrs: { class: 'neon-js-object-indent' } }, ...this.renderLineBlock(token));
            }
        });
    }
}
